"""Builds backend/data/DATA_CARD.md from the generator's own documentation, so the card cannot drift from the code."""
from __future__ import annotations

from .cohort import AGE_BANDS, BP_MODEL, DISTRIBUTIONS, FIELDS, RAISED_DBP, RAISED_SBP, REGION_NAMES, SEVERE_DBP, SEVERE_SBP, SEX


def _dist(d: dict) -> str:
    return ", ".join(f"{k} {v:.0%}" if not isinstance(v, dict) else f"{k}: ({_dist(v)})" for k, v in d.items())


def build(seed: int, stats: dict) -> str:
    m = BP_MODEL
    lines = [
        "# Data card: synthetic screened cohorts", "",
        "Generated by `python -m app.sim.run` (code in `backend/app/sim/cohort.py`). Do not edit by hand.", "",
        "## Statement", "",
        "Every record is fictional. No record corresponds to a real person, patient or clinician. People are identified only by a generated id such as `AUH-00001`. There are no names.", "",
        "No Synthea: Java is not available in the build environment. A purpose-built seeded generator was used instead.", "",
        "## Reproducibility", "",
        f"- Seed: {seed}. Generator: numpy `default_rng([seed, region_index])`. The same seed gives byte-identical CSV files.",
        "- Size: one file per region, 5,000 synthetic screened people each.", "",
        "## Files", "",
        "- `cohort_auh.csv`: Abu Dhabi.", "- `cohort_yde.csv`: Yaounde.", "",
        "## Fields", "",
        "| Field | Meaning |", "|---|---|",
        "| person_id | Generated id, region prefix plus a running number. |",
        "| region | `AUH` (Abu Dhabi) or `YDE` (Yaounde). |",
        "| age | Whole years, 18 to 85. |",
        "| age_band | " + ", ".join(f"`{b}`" for b in AGE_BANDS) + ". The same bands as the live dashboard. |",
        "| sex | " + " or ".join(f"`{c}`" for c in SEX) + ", the same codes as the live dashboard (F female, M male). |",
        "| nationality_group | Abu Dhabi: Emirati, Expatriate Arab, South Asian, Other. Yaounde: Cameroonian (one group). |",
        "| preferred_language | Abu Dhabi: `ar` or `en`. Yaounde: `fr` or `en`. |",
        "| insurance_type | Abu Dhabi: thiqa, basic_enhanced, private, none. Yaounde: none, mutual_or_private, employer. |",
        "| phone_channel | `app`, `sms` or `whatsapp`. |",
        "| screening_sbp, screening_dbp | Single screening reading in mmHg. |",
        "| urgency | `SEVERE`, `RAISED` or `NOT_ACTIONABLE`, from the SPEC thresholds below. |",
        "| actionable | `true` when urgency is SEVERE or RAISED. Only these people enter the pathway simulation. |", "",
        "Check: the CSV header has exactly these fields: " + ", ".join(f"`{f}`" for f in FIELDS) + ".", "",
        "## Assumptions (none is calibrated to a real population)", "",
        "These distributions were chosen to make a plausible demonstration population. They are assumptions, not estimates.", "",
    ]
    for region, d in DISTRIBUTIONS.items():
        lines += [f"### {REGION_NAMES[region]} ({region})", "",
                  f"- Age: {d['age']}", f"- Sex: {_dist(d['sex'])}.", f"- Nationality group: {_dist(d['nationality_group'])}.",
                  f"- Preferred language: {_dist(d['preferred_language'])}.", f"- Insurance: {_dist(d['insurance_type'])}. (Abu Dhabi: Emirati rows use the Emirati entry, everyone else the default entry.)",
                  f"- Phone channel: {_dist(d['phone_channel'])}.", ""]
    lines += [
        "### Blood pressure (both regions)", "",
        f"- Systolic = {m['sbp_base']:.0f} + {m['sbp_per_year']} x (age - 18) + {m['sbp_male']:.0f} if male + Normal(0, {m['sbp_noise_sd']:.0f}) + raised_extra.",
        f"- raised_extra is 0 for {1 - m['raised_share']:.0%} of people and Normal({m['raised_mean']:.0f}, {m['raised_sd']:.0f}) for the other {m['raised_share']:.0%}. This is a simple way to give the population a raised tail.",
        f"- Diastolic = {m['dbp_base']:.0f} + {m['dbp_per_sbp']} x (systolic - expected systolic) + {m['dbp_per_year']} x (age - 40) + Normal(0, {m['dbp_noise_sd']}).",
        "- Values are rounded to whole mmHg and clipped to 80 to 240 (systolic) and 45 to 140 (diastolic).",
        f"- Threshold used for `urgency`: SEVERE at systolic {SEVERE_SBP} or more or diastolic {SEVERE_DBP} or more; RAISED at systolic {RAISED_SBP} to {SEVERE_SBP - 1} or diastolic {RAISED_DBP} to {SEVERE_DBP - 1}. They are read from the engine config (`backend/app/engine/config.yaml`), where they are placeholder values pending clinician sign-off. They are not clinically validated.",
        "- The actionable share is a by-product of the model above. It is not calibrated to any published prevalence.", "",
        "## Resulting summary", "", "| Region | People | Actionable | Actionable share | Severe | Mean age | Mean systolic | Mean diastolic |", "|---|---|---|---|---|---|---|---|",
    ]
    for region, s in stats.items():
        lines.append(f"| {region} | {s['people']} | {s['actionable']} | {s['actionable_share']:.1%} | {s['severe']} | {s['mean_age']} | {s['mean_sbp']} | {s['mean_dbp']} |")
    lines += ["", "## Intended use and limits", "",
              "- To drive the baseline versus with-loop simulation and show what the dashboard measures.",
              "- Simulated results on these people are not evidence of clinical effectiveness.",
              "- Not for training clinical models, estimating prevalence or any decision about real people.", ""]
    return "\n".join(lines)
